import React, { useEffect, useState } from 'react';
import { Zap } from 'lucide-react';

const LiveStatus: React.FC = () => {
  const [status, setStatus] = useState("جاري فك تجميد مهمة للمستخدم 492***...");

  useEffect(() => {
    const statuses = [
      "تم سحب 450 USDT بنجاح للمستخدم 902***",
      "جاري معالجة المهمة 17 للمستخدم 112***",
      "تمت الموافقة على طلب فك التجميد رقم #8821",
      "انضم 5 مستخدمين جدد للمنصة الآن"
    ];
    let i = 0;
    const interval = setInterval(() => {
      i = (i + 1) % statuses.length;
      setStatus(statuses[i]);
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="bg-blue-50 border-l-4 border-blue-500 p-3 my-4 rounded-r-xl flex items-center gap-3 shadow-sm">
      <Zap size={18} className="text-blue-500 animate-pulse flex-shrink-0" />
      <span className="text-blue-800 text-xs font-medium truncate">{status}</span>
    </div>
  );
};

