import React, { useState, useEffect } from 'react';
import { Home, ShieldAlert, LifeBuoy, FileClock, User } from 'lucide-react';

interface BottomNavProps {
  activeTab: string;
  onTabChange: (tab: string) => void;
}

const navItems = [
  { id: 'Home', icon: Home, label: 'الرئيسية' },
  { id: 'Recovery', icon: ShieldAlert, label: 'استرداد' },
  { id: 'History', icon: FileClock, label: 'السجلات' },
  { id: 'Support', icon: LifeBuoy, label: 'المساعدة' },
  { id: 'Profile', icon: User, label: 'حسابي' },
];

const BottomNav: React.FC<BottomNavProps> = ({ activeTab, onTabChange }) => {
  const [blockedId, setBlockedId] = useState<string | null>(null);

  const blockedTabs = ['History', 'Support', 'Profile'];

  const handleTabClick = (id: string) => {
    if (blockedTabs.includes(id)) {
      setBlockedId(id);
      // إخفاء رمز الحظر بعد ثانية واحدة
      setTimeout(() => setBlockedId(null), 1000);
      return;
    }
    onTabChange(id);
  };

  return (
    <nav className="fixed bottom-0 left-0 right-0 max-w-[430px] mx-auto bg-white/90 backdrop-blur-lg border-t border-gray-100 flex justify-around py-3 px-1 z-50 rounded-t-3xl shadow-[0_-10px_25px_rgba(0,0,0,0.05)]">
      {navItems.map((item) => {
        const Icon = item.icon;
        const isActive = activeTab === item.id;
        const isBlocked = blockedId === item.id;

        return (
          <button
            key={item.id}
            onClick={() => handleTabClick(item.id)}
            className="flex flex-col items-center gap-1 flex-1 transition-all relative"
          >
            {/* رمز الحظر يظهر فوق الأيقونة عند الضغط */}
            {isBlocked && (
              <div className="absolute -top-4 left-1/2 -translate-x-1/2 text-2xl animate-bounce z-10">
                🚫
              </div>
            )}

            <div className={`p-1.5 rounded-xl transition-all ${isActive ? "bg-[#9B4A4E] text-white shadow-lg shadow-[#9B4A4E]/20" : "text-gray-400"}`}>
              <Icon size={22} strokeWidth={isActive ? 2.5 : 2} />
            </div>
            <span className={`text-[9px] font-bold ${isActive ? "text-[#9B4A4E]" : "text-gray-400"}`}>
              {item.label}
            </span>
          </button>
        );
      })}
    </nav>
  );
};

export default BottomNav;

