        const isActive = activeTab === item.id;
        const isBlocked = blockedId === item.id;

        return (
          <button
            key={item.id}
            onClick={() => handleTabClick(item.id)}
            className="flex flex-col items-center gap-1 flex-1 transition-all relative outline-none"
          >
