import React, { useState, useRef, useEffect } from 'react';
import { ShieldAlert, Gavel, Send, User, Headphones } from 'lucide-react';

interface Message {
  id: number;
  text: string;
  sender: 'user' | 'support';
  time: string;
}

const RecoveryForm: React.FC = () => {
  const [isChatActive, setIsChatActive] = useState(false);
  const [formData, setFormData] = useState({
    link: '',
    missionId: '',
    amount: '',
    reason: 'تجميد الرصيد'
  });
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isChatActive) {
      scrollToBottom();
    }
  }, [messages, isChatActive]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const initialMessage = `
🚨 *طلب إيقاف مهمة واسترداد رصيد* 🚨

📍 **رابط المنصة:** ${formData.link || 'غير محدد'}
🔢 **رقم المهمة:** ${formData.missionId || 'غير محدد'}
💰 **المبلغ المحتجز:** ${formData.amount || '0.00'} USDT
📝 **سبب الشكوى:** ${formData.reason}

---
يرجى مراجعة الطلب واتخاذ الإجراءات القانونية اللازمة لإيقاف السحب وتجميد المهمة فوراً.
    `.trim();

    const newMsg: Message = {
      id: Date.now(),
      text: initialMessage,
      sender: 'user',
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages([newMsg]);
    setIsChatActive(true);

    // الرد التلقائي من الدعم بعد ثانية
    setTimeout(() => {
      const supportReply: Message = {
        id: Date.now() + 1,
        text: "أهلاً بك في مكتب فض النزاعات. لقد استلمنا تفاصيل شكواك بنجاح. جاري الآن فحص السجلات الفنية للمنصة المذكورة وإيقاف المهمة برمجياً. يرجى البقاء متصلاً.",
        sender: 'support',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, supportReply]);
    }, 1500);
  };

  const handleSendMessage = () => {
    if (!inputValue.trim()) return;
    const newMsg: Message = {
      id: Date.now(),
      text: inputValue,
      sender: 'user',
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };
    setMessages(prev => [...prev, newMsg]);
    setInputValue('');
  };

  if (isChatActive) {
    return (
      <div className="bg-white rounded-3xl shadow-xl border border-gray-100 flex flex-col h-[500px] overflow-hidden">
        {/* Chat Header */}
        <div className="bg-gradient-to-r from-[#9B4A4E] to-[#7C4A50] p-4 flex items-center justify-between text-white">
          <div className="flex items-center gap-3">
            <div className="relative">
              <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                <Headphones size={20} />
              </div>
              <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white rounded-full"></div>
            </div>
            <div className="flex flex-col text-right">
              <span className="text-sm font-bold">الدعم الفني المباشر</span>
              <span className="text-[10px] opacity-80">متصل الآن - معالجة الشكوى</span>
            </div>
          </div>
          <button onClick={() => setIsChatActive(false)} className="text-[10px] bg-white/10 px-2 py-1 rounded-lg">إغلاق</button>
        </div>

        {/* Chat Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50 flex flex-col">
          {messages.map((msg) => (
            <div 
              key={msg.id} 
              className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                msg.sender === 'user' 
                  ? 'bg-[#9B4A4E] text-white self-end rounded-tr-none text-right' 
                  : 'bg-white text-gray-800 self-start rounded-tl-none text-right border border-gray-100'
              }`}
            >
              <div className="whitespace-pre-wrap">{msg.text}</div>
              <div className={`text-[9px] mt-1 opacity-60 ${msg.sender === 'user' ? 'text-left' : 'text-right'}`}>
                {msg.time}
              </div>
            </div>
          ))}
          <div ref={chatEndRef} />
        </div>

        {/* Chat Input */}
        <div className="p-3 bg-white border-t border-gray-100 flex gap-2">
          <input 
            type="text" 
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            placeholder="اكتب رسالتك هنا..."
            className="flex-1 bg-gray-100 border-none rounded-xl px-4 py-2 text-sm focus:ring-1 focus:ring-[#9B4A4E] text-right"
            dir="rtl"
          />
          <button 
            onClick={handleSendMessage}
            className="bg-[#9B4A4E] text-white p-2 rounded-xl active:scale-90 transition-transform"
          >
            <Send size={18} className="rotate-180" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl border border-gray-100 min-h-[500px] flex flex-col justify-between">
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="text-xs font-bold text-gray-500 mb-1 block text-right">رابط المنصة محل الشكوى</label>
          <input 
            type="text" 
            required
            value={formData.link}
            onChange={(e) => setFormData({...formData, link: e.target.value})}
            placeholder="مثال: https://amazon-task-vip.com" 
            dir="ltr"
            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#9B4A4E] transition-all text-right"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-xs font-bold text-gray-500 mb-1 block text-right">رقم المهمة</label>
            <input 
              type="number" 
              required
              value={formData.missionId}
              onChange={(e) => setFormData({...formData, missionId: e.target.value})}
              placeholder="مثال: 17" 
              className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#9B4A4E] transition-all text-right"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-gray-500 mb-1 block text-right">المبلغ المحتجز</label>
            <input 
              type="text" 
              required
              value={formData.amount}
              onChange={(e) => setFormData({...formData, amount: e.target.value})}
              placeholder="0.00 USDT" 
              className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#9B4A4E] transition-all text-right"
            />
          </div>
        </div>

        <div>
          <label className="text-xs font-bold text-gray-500 mb-1 block text-right">سبب الشكوى</label>
          <select 
            value={formData.reason}
            onChange={(e) => setFormData({...formData, reason: e.target.value})}
            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#9B4A4E] transition-all text-right"
          >
            <option>تجميد الرصيد</option>
            <option>طلب إيداع إضافي تعجيزي</option>
            <option>خلل في النظام</option>
            <option>أخرى</option>
          </select>
        </div>

        <button 
          type="submit"
          className="w-full bg-gradient-to-r from-[#9B4A4E] to-[#7C4A50] text-white font-bold py-4 rounded-2xl shadow-[#9B4A4E]/20 shadow-lg flex items-center justify-center gap-2 active:scale-[0.98] transition-all"
        >
          <Gavel size={20} />
          إرسال شكوى رسمية وإيقاف المهمة
        </button>
      </form>

      <div className="mt-6 pt-6 border-t border-dashed border-gray-200">
        <div className="flex items-center justify-between text-[10px] text-gray-400 font-bold uppercase tracking-wider">
          <span className="flex items-center gap-1"><ShieldAlert size={14} className="text-red-500" /> قانوني 100%</span>
          <span className="flex items-center gap-1"><ShieldAlert size={14} className="text-red-500" /> إيقاف فوري</span>
          <span className="flex items-center gap-1"><ShieldAlert size={14} className="text-red-500" /> حماية الخصوصية</span>
        </div>
      </div>
    </div>
  );
};

